              "bullets": [],
              "note": "",
              "price": "",
              "ctaLabel": "",
              "ctaHref": "",
              "variant": "compact-media",
              "mediaUrl": "/images/tenants/resonantweaver/About-Portrait.png",
              "mediaAlt": "Portrait of Marthe",
              "mediaPortrait": true
            }
          ]
        }
      }
    }
  ]
}$rwjson$::jsonb);

