            },
            {
              "marker": "02",
              "title": "Awareness and Perception Training",
              "copy": "A deeper training in subtle perception. Learn to notice what you are sensing, recognise how information reaches you, and distinguish direct perception from emotion, expectation, projection, and mental interpretation. The training begins with the body and develops into grounded discernment, clear energetic boundaries, and a more conscious relationship with what you perceive.",
              "imageUrl": "",
              "imageAlt": "",
              "price": "",
              "statusLabel": "In development",
              "statusReady": false,
              "linkLabel": "Get notified when it opens",
