          "headingRole": "display",
          "headingSize": "clamp(1.75rem, 3.2vw, 2.65rem)",
          "headingWeight": 520,
          "headingTracking": "-0.025em",
          "headingLh": "0.98",
          "headingGap": "0",
          "headingInk": "rgb(232, 229, 218)",
          "copyRole": "body",
          "copyLh": "1.72",
          "copyGap": "16px",
          "copyMaxWidth": "72ch",
